import{_ as e,o,c as a,a2 as l}from"./chunks/framework.z3u3TMv0.js";const m=JSON.parse('{"title":"Local tools overview","description":"Compare Ollama, LM Studio, KoboldCPP, llama.cpp, LocalAI, Jan, text-generation-webui — pick a local OpenAI-compatible tool for MiniTavern.","frontmatter":{"title":"Local tools overview","description":"Compare Ollama, LM Studio, KoboldCPP, llama.cpp, LocalAI, Jan, text-generation-webui — pick a local OpenAI-compatible tool for MiniTavern.","head":[["meta",{"name":"keywords","content":"tavern,AI tavern,MiniTavern,AI companion,AI friend,AI local chat,Silly Tavern,SillyTavern,Silly Tavern mobile,Silly Tavern Android,Silly Tavern iOS,AI roleplay,character card,AI chat,mobile AI,offline AI,AI story,local LLM,Ollama,LM Studio,lorebook,regex,BYOK,user guide,docs,AI chat client"}],["meta",{"property":"og:title","content":"Local tools overview · MiniTavern Docs"}],["meta",{"property":"og:description","content":"Compare Ollama, LM Studio, KoboldCPP, llama.cpp, LocalAI, Jan, text-generation-webui — pick a local OpenAI-compatible tool for MiniTavern."}],["meta",{"property":"og:url","content":"https://minitavern.github.io/ultra_guides/en/local/tools"}],["link",{"rel":"canonical","href":"https://minitavern.github.io/ultra_guides/en/local/tools"}]]},"headers":[],"relativePath":"en/local/tools.md","filePath":"en/local/tools.md","lastUpdated":1787224147000}'),n={name:"en/local/tools.md"};function r(i,t,d,s,c,p){return o(),a("div",null,[...t[0]||(t[0]=[l('<h1 id="tools-overview" tabindex="-1">Tools overview <a class="header-anchor" href="#tools-overview" aria-label="Permalink to &quot;Tools overview&quot;">​</a></h1><p>MiniTavern can use a <strong>Custom</strong> model link whenever the backend speaks <strong>OpenAI-compatible</strong> Chat Completions (or can map to it). Use the table to pick a tool.</p><h2 id="comparison" tabindex="-1">Comparison <a class="header-anchor" href="#comparison" aria-label="Permalink to &quot;Comparison&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Tool</th><th>Difficulty</th><th>UI</th><th>Pull models</th><th>Roleplay fit</th><th>Typical Base URL</th></tr></thead><tbody><tr><td><a href="/ultra_guides/en/ollama/install">Ollama</a></td><td>★☆☆</td><td>Tray + CLI</td><td><code>ollama pull</code></td><td>Strong general chat</td><td><code>http://IP:11434/v1</code></td></tr><tr><td><a href="/ultra_guides/en/lmstudio/install">LM Studio</a></td><td>★☆☆</td><td>Full GUI</td><td>In-app download</td><td>General</td><td><code>http://IP:1234/v1</code></td></tr><tr><td><a href="/ultra_guides/en/koboldcpp/install">KoboldCPP</a></td><td>★★☆</td><td>Light GUI/CLI</td><td>Bring your own GGUF</td><td><strong>Common in RP communities</strong></td><td><code>http://IP:5001/v1</code></td></tr><tr><td><a href="/ultra_guides/en/llamacpp/install">llama.cpp server</a></td><td>★★★</td><td>CLI</td><td>Bring your own GGUF</td><td>Controllable, light</td><td><code>http://IP:8080/v1</code></td></tr><tr><td><a href="/ultra_guides/en/localai/install">LocalAI</a></td><td>★★☆</td><td>API / optional UI</td><td>YAML / images</td><td>Multi-backend</td><td><code>http://IP:8080/v1</code></td></tr><tr><td><a href="/ultra_guides/en/jan/install">Jan</a></td><td>★☆☆</td><td>Desktop app</td><td>In-app</td><td>General</td><td>See app “API” page</td></tr><tr><td><a href="/ultra_guides/en/textgen/install">text-generation-webui</a></td><td>★★★</td><td>Web UI</td><td>Many extensions</td><td>Plugin ecosystem</td><td>After OpenAI extension</td></tr></tbody></table><h2 id="how-to-choose-one-line" tabindex="-1">How to choose (one line) <a class="header-anchor" href="#how-to-choose-one-line" aria-label="Permalink to &quot;How to choose (one line)&quot;">​</a></h2><ol><li><strong>Just get it working</strong>: Ollama or LM Studio → <a href="/ultra_guides/en/quickstart">30-minute quickstart</a></li><li><strong>Care about RP presets / samplers</strong>: KoboldCPP</li><li><strong>Have GGUF, want minimal deps</strong>: llama.cpp <code>llama-server</code></li><li><strong>Already on Docker / want a compatibility layer</strong>: LocalAI</li><li><strong>Want an all-in-one desktop assistant</strong>: Jan</li><li><strong>Already run oobabooga</strong>: enable the OpenAI-compatible extension, then connect MiniTavern</li></ol><h2 id="shared-requirements" tabindex="-1">Shared requirements <a class="header-anchor" href="#shared-requirements" aria-label="Permalink to &quot;Shared requirements&quot;">​</a></h2><p>Whatever you pick:</p><ol><li>Listen on the <strong>LAN</strong> (<code>0.0.0.0</code> or “allow LAN devices”), not only <code>127.0.0.1</code></li><li>Allow the port in the firewall</li><li>On the phone use the <strong>PC LAN IP</strong>, Base URL with <code>/v1</code> (unless that tool’s docs say otherwise)</li><li>Model name must <strong>exactly match</strong> the id / name shown in the tool</li></ol><p>Next: <a href="./models">Recommended models</a> · <a href="/ultra_guides/en/connect-app/minitavern">Configure in MiniTavern</a></p>',10)])])}const u=e(n,[["render",r]]);export{m as __pageData,u as default};
